<script setup>import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {api} from '../services/api';import {store,saveCart} from '../main';const route=useRoute(),product=ref(null);onMounted(async()=>product.value=(await api.product(route.params.id)).data);function add(){const x=store.cart.find(i=>i.productId===product.value.id);if(x)x.quantity++;else store.cart.push({productId:product.value.id,name:product.value.name,sku:product.value.sku,price:product.value.price,quantity:1});saveCart()}</script>
<template><section v-if="product" class="detail"><div class="breadcrumbs">Home / Shop / {{product.name}}</div><div class="detail-grid"><div class="detail-image"><div class="device-art large">{{product.brand}}</div></div><div><span class="eyebrow">{{product.brand}} · SKU {{product.sku}}</span><h1>{{product.name}}</h1><p class="rating">★★★★★ <span>4.8 · verified purchases</span></p><div class="price">${{product.price.toLocaleString(undefined,{minimumFractionDigits:2})}} <del v-if="product.compareAtPrice">${{product.compareAtPrice.toLocaleString(undefined,{minimumFractionDigits:2})}}</del></div><p>{{product.description}}</p><div class="stock">{{product.stock>0?'IN STOCK · Ships within 24 hours':'OUT OF STOCK'}}</div><div class="actions"><button class="btn primary" :disabled="!product.stock" @click="add">Add to Cart</button><router-link class="btn ghost" to="/cart">View Cart</router-link></div><div class="specs"><div v-for="(v,k) in product.attributes" :key="k"><small>{{k}}</small><b>{{v}}</b></div></div></div></div></section></template>
